function compatible(id,hero,cell,D){if(id!=='mana'&&id!=='summon')return ids.has(id);const skills=D.skills.filter(s=>s.heroId===hero&&s.cell===cell);if(id==='mana')return skills[0]?.resource?.kind==='mana';if(id==='summon')return skills.some(s=>s.actions.some(a=>['pet','summon','turret'].includes(a.op)||['four-call','overdrive','companions','wolf-call','alpha-pack','thorn-sentries','ancient-tree','prototype-turret','twin-sentries','bastion-protocol','culture-pair','chimera-synthesis','perfect-evolution','phylactery'].includes(a.kind)));return ids.has(id);}
